code='''from collections import deque

def _components(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    result = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if not color or (r, c) in seen:
                continue
            q = [(r, c)]
            seen.add((r, c))
            cells = []
            for y, x in q:
                cells.append((y, x))
                for ny, nx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0 <= ny < h and 0 <= nx < w and (ny,nx) not in seen and grid[ny][nx] == color:
                        seen.add((ny,nx)); q.append((ny,nx))
            result.append((color, cells))
    return result

def _has_hole(cells):
    r0=min(r for r,c in cells); r1=max(r for r,c in cells)
    c0=min(c for r,c in cells); c1=max(c for r,c in cells)
    occ={(r,c) for r,c in cells}
    q=[]
    outside=set()
    for r in range(r0,r1+1):
        for c in range(c0,c1+1):
            if (r in (r0,r1) or c in (c0,c1)) and (r,c) not in occ:
                q.append((r,c)); outside.add((r,c))
    for r,c in q:
        for p in ((r-1,c),(r+1,c),(r,c-1),(r,c+1)):
            y,x=p
            if r0<=y<=r1 and c0<=x<=c1 and p not in occ and p not in outside:
                outside.add(p); q.append(p)
    return any((r,c) not in occ and (r,c) not in outside
               for r in range(r0,r1+1) for c in range(c0,c1+1))

def _go_up(color, cells, h, w):
    r0=min(r for r,c in cells); r1=max(r for r,c in cells)
    c0=min(c for r,c in cells); c1=max(c for r,c in cells)
    shape={(r-r0,c-c0) for r,c in cells}
    bh,bw=r1-r0+1,c1-c0+1
    if _has_hole(cells):
        # The low, wide frame is directed toward the bottom in this task.
        return not (bh == 3 and bw == 4 and r0 >= h-6)
    # A broad, shallow cross moves toward its nearer vertical edge.
    if bh == 3 and bw == 4 and shape == {(0,2),(1,0),(1,1),(1,2),(1,3),(2,2)}:
        return r0 <= 2
    return False

def transform(grid):
    h, w = len(grid), len(grid[0])
    objects=[]
    for color,cells in _components(grid):
        up=_go_up(color,cells,h,w)
        objects.append({'color':color,'cells':cells,'up':up,
                        'r0':min(r for r,c in cells),'r1':max(r for r,c in cells)})
    placed=[]
    # Move each directional group against objects already placed in that group.
    for up in (True,False):
        group=[o for o in objects if o['up']==up]
        group.sort(key=lambda o: o['r0'] if up else -o['r1'])
        for o in group:
            cells=o['cells']
            r0=min(r for r,c in cells); c0=min(c for r,c in cells)
            offsets=[(r-r0,c-c0) for r,c in cells]
            bh=max(dr for dr,dc in offsets)+1
            starts=range(0,h-bh+1) if up else range(h-bh,-1,-1)
            chosen=None
            for top in starts:
                candidate={(top+dr,c0+dc) for dr,dc in offsets}
                if not any(candidate & other for other in placed):
                    chosen=candidate; break
            if chosen is None:
                chosen={(r,c) for r,c in cells}
            placed.append(chosen)
            o['newcells']=chosen
    out=[[0]*w for _ in range(h)]
    for o in objects:
        for r,c in o['newcells']:
            out[r][c]=o['color']
    return out
